(function() {
  const LANGUAGE_TAGS = new Set([
    'English', 'Spanish', 'Portuguese', 'Japanese', 'Korean', 'French',
    'German', 'Russian', 'Turkish', 'Chinese', 'Arabic', 'Hindi',
    'Italian', 'Dutch', 'Polish', 'Vietnamese', 'Thai', 'Indonesian',
    'Malay', 'Filipino', 'Tagalog', 'Swedish', 'Norwegian', 'Danish',
    'Finnish', 'Greek', 'Czech', 'Hungarian', 'Romanian', 'Bulgarian',
    'Serbian', 'Croatian', 'Slovak', 'Slovenian', 'Hebrew', 'Ukrainian',
    'Latvian', 'Lithuanian', 'Estonian', 'Icelandic', 'Irish',
    'Welsh', 'Catalan', 'Galician', 'Basque', 'Bengali', 'Tamil',
    'Telugu', 'Marathi', 'Punjabi', 'Gujarati', 'Urdu', 'Persian',
    'Farsi', 'Swahili', 'Amharic', 'Hausa', 'Yoruba', 'Zulu',
    'Afrikaans', 'Maltese', 'Georgian', 'Armenian', 'Kazakh',
    'Uzbek', 'Mongolian', 'Nepali', 'Sinhala', 'Khmer', 'Lao',
    'Burmese', 'Myanmar', 'Tibetan', 'Macedonian', 'Albanian',
    'Bosnian', 'Kurdish', 'Pashto', 'Dari', 'Somali', 'Malagasy',
    'Haitian', 'Creole', 'Quechua', 'Aymara', 'Guarani',
    'Navajo', 'Cherokee', 'Cree', 'Inuktitut',
    'Latin America', 'Brazil', 'India', 'Japan', 'Korea',
    'Southeast Asia', 'Middle East', 'Africa', 'Eastern Europe',
    'Scandinavia', 'Nordic', 'Baltic', 'Slavic', 'Mediterranean',
    'North America', 'Europe', 'Asia', 'Oceania',
    'Latam', 'Latin American Spanish', 'Brazilian Portuguese',
    'Mandarin', 'Cantonese', 'Traditional Chinese', 'Simplified Chinese',
    'Japanese (Japan)', 'Korean (Korea)', 'English (UK)', 'English (US)',
    'Spanish (Spain)', 'Portuguese (Brazil)', 'French (France)',
    'German (Germany)', 'Italian (Italy)', 'Russian (Russia)',
    'Turkish (Turkey)', 'Arabic (MENA)', 'Hindi (India)'
  ]);

  const tagsContainer = element.querySelector('.fsLBGq');
  if (!tagsContainer) return;

  const innerWrapper = tagsContainer.querySelector('.cYTUJE');
  if (!innerWrapper) return;

  const allTags = innerWrapper.querySelectorAll('.tw-tag');
  let languageTagsFound = [];

  allTags.forEach(function(tag) {
    var tagText = tag.getAttribute('data-a-target') || '';
    var ariaLabel = tag.getAttribute('aria-label') || '';
    var displayText = tag.textContent.trim();

    var isLanguage = false;
    if (LANGUAGE_TAGS.has(tagText)) {
      isLanguage = true;
    }
    if (!isLanguage && LANGUAGE_TAGS.has(displayText)) {
      isLanguage = true;
    }
    if (!isLanguage) {
      var lowerLabel = ariaLabel.toLowerCase();
      var lowerTarget = tagText.toLowerCase();
      LANGUAGE_TAGS.forEach(function(lang) {
        if (lowerLabel.includes(lang.toLowerCase()) || lowerTarget.includes(lang.toLowerCase())) {
          isLanguage = true;
        }
      });
    }

    if (isLanguage) {
      languageTagsFound.push(tag);
    }
  });

  if (languageTagsFound.length === 0) return;

  var textWrapper = element.querySelector('.fzKxJT');
  if (!textWrapper) return;

  var titleLink = textWrapper.querySelector('[data-test-selector="TitleAndChannel"]');
  if (!titleLink) return;

  var fragment = document.createDocumentFragment();
  languageTagsFound.forEach(function(tag) {
    tag.parentNode.removeChild(tag);
    fragment.appendChild(tag);
  });

  textWrapper.insertBefore(fragment, titleLink);
})();
